//! Golden-page tests: render fixed pages and compare them with `tests/golden/*.png`.
//!
//! - Pages are rendered through `ink_formats::open` + `Document::render_page` at
//!   1272 x 1696 with `LayoutSettings::for_screen` or a variant of it (page content
//!   only, no reader footer). The books are `testdata/` plus the feature fixtures in
//!   `crates/ink-html/tests/fixtures/` (generated by `examples/make_fixtures.rs`).
//! - Tolerance: none by default. Width, height and every pixel must match exactly; one
//!   changed pixel fails the test. `INK_GOLDEN_TOLERANCE=N` lets up to N pixels per page
//!   differ: CI sets it, because another platform's float rounding moves a pixel or two
//!   of the goldens made on the development machine.
//! - On a mismatch the actual page and a diff image (RGB: changed pixels red, the rest
//!   the golden in light gray) go to `$INK_GOLDEN_OUT` (default `target/golden-out`).
//! - `INK_GOLDEN_UPDATE=1` rewrites the goldens instead (use `scripts/golden-update.sh`,
//!   which also keeps the diff images).
//! - `INK_GOLDEN_DIR` reads goldens from another directory (used to prove that a
//!   1-pixel change fails).
//!
//! Add a case by adding a line to `CASES` and running
//! `scripts/golden-update.sh`.

use ink_device::Canvas;
use ink_doc::{Document, LayoutSettings};
use std::path::{Path, PathBuf};

/// Layout variant of a case.
#[derive(Clone, Copy)]
enum Variant {
    /// `LayoutSettings::for_screen(1272, 1696)`.
    Default,
    /// Hyphenation on.
    Hyphenate,
    /// Smaller font (30 px), publisher styles off.
    SmallNoPublisher,
    /// Publisher styles off.
    NoPublisher,
    /// Annotations of [`CodepointAnnotator`].
    Annotated,
}

/// A test annotator: every CJK ideograph gets its code point in hex.
struct CodepointAnnotator;

impl ink_doc::TextAnnotator for CodepointAnnotator {
    fn id(&self) -> &str {
        "codepoints"
    }
    fn version(&self) -> u64 {
        1
    }
    fn wants(&self, p: &str, _lang: Option<&str>) -> bool {
        p.chars().any(is_ideograph)
    }
    fn annotate(&self, p: &str, _lang: Option<&str>) -> Vec<ink_doc::Annotation> {
        p.char_indices().filter(|&(_, c)| is_ideograph(c)).map(|(i, c)| ink_doc::Annotation::over(i..i + c.len_utf8(), format!("{:x}", c as u32))).collect()
    }
}

fn is_ideograph(c: char) -> bool {
    ('\u{4e00}'..='\u{9fff}').contains(&c)
}

/// (golden name prefix, book under the repo root, 0-based pages, layout).
const CASES: &[(&str, &str, &[usize], Variant)] = &[
    ("juliet", "testdata/juliet.epub", &[0, 1, 2, 5, 50], Variant::Default),
    ("juliet-small-nopub", "testdata/juliet.epub", &[3, 40], Variant::SmallNoPublisher),
    ("synthetic", "testdata/synthetic.epub", &[0, 1, 2], Variant::Default),
    ("ws", "crates/ink-html/tests/fixtures/ws.epub", &[0, 1], Variant::Default),
    ("css-selectors", "crates/ink-html/tests/fixtures/css-selectors.epub", &[0], Variant::Default),
    ("css-selectors-nopub", "crates/ink-html/tests/fixtures/css-selectors.epub", &[0], Variant::NoPublisher),
    ("css-text", "crates/ink-html/tests/fixtures/css-text.epub", &[0, 1, 2, 3], Variant::Default),
    ("css-box", "crates/ink-html/tests/fixtures/css-box.epub", &[0, 1, 2, 3, 4], Variant::Default),
    ("fonts", "crates/ink-html/tests/fixtures/fonts.epub", &[0], Variant::Default),
    ("images", "crates/ink-html/tests/fixtures/images.epub", &[0, 1, 2, 3, 4, 5], Variant::Default),
    ("tables-lists", "crates/ink-html/tests/fixtures/tables-lists.epub", &[0, 1, 3, 4], Variant::Default),
    ("notes", "crates/ink-html/tests/fixtures/notes.epub", &[0, 1], Variant::Default),
    ("lang", "crates/ink-html/tests/fixtures/lang.epub", &[0], Variant::Hyphenate),
    ("pagelist", "crates/ink-html/tests/fixtures/pagelist.epub", &[0, 1], Variant::Default),
    ("malformed", "crates/ink-html/tests/fixtures/malformed.epub", &[0, 1, 2], Variant::Default),
    ("ruby", "crates/ink-html/tests/fixtures/ruby.epub", &[0], Variant::Default),
    ("ruby-annotated", "crates/ink-html/tests/fixtures/ruby.epub", &[0], Variant::Annotated),
];

fn settings(v: Variant) -> LayoutSettings {
    let mut s = LayoutSettings::for_screen(1272, 1696);
    match v {
        Variant::Default => {}
        Variant::Hyphenate => s.hyphenate = true,
        Variant::SmallNoPublisher => {
            s.font_px = 30.0;
            s.publisher_styles = false;
        }
        Variant::NoPublisher => s.publisher_styles = false,
        Variant::Annotated => s.annotators = vec![ink_doc::AnnotatorHandle::new(std::sync::Arc::new(CodepointAnnotator))],
    }
    s
}

/// The repository root (`INK_MANIFEST_DIR/../..` when set, for test binaries run on the
/// Kindle emulator with the fixtures and goldens copied there).
fn root() -> PathBuf {
    std::env::var_os("INK_MANIFEST_DIR").map(PathBuf::from).unwrap_or_else(|| Path::new(env!("CARGO_MANIFEST_DIR")).to_path_buf()).join("../..")
}

fn golden_dir() -> PathBuf {
    std::env::var_os("INK_GOLDEN_DIR").map(PathBuf::from).unwrap_or_else(|| root().join("tests/golden"))
}

fn out_dir() -> PathBuf {
    std::env::var_os("INK_GOLDEN_OUT").map(PathBuf::from).unwrap_or_else(|| root().join("target/golden-out"))
}

/// Number of differing pixels, or `None` when the sizes differ.
fn count_diff(a: &Canvas, b: &Canvas) -> Option<usize> {
    if (a.width, a.height) != (b.width, b.height) {
        return None;
    }
    Some(a.pixels.iter().zip(&b.pixels).filter(|(x, y)| x != y).count())
}

/// RGB diff image: changed pixels red, others the expected image in light gray.
fn write_diff(expected: &Canvas, actual: &Canvas, path: &Path) {
    let (w, h) = (actual.width, actual.height);
    let mut rgb = Vec::with_capacity(w * h * 3);
    for i in 0..w * h {
        let a = actual.pixels[i];
        let e = expected.pixels.get(i).copied().unwrap_or(255);
        if a != e || (expected.width, expected.height) != (w, h) {
            rgb.extend_from_slice(&[255, 0, 0]);
        } else {
            let g = 160 + e / 3;
            rgb.extend_from_slice(&[g, g, g]);
        }
    }
    let file = std::io::BufWriter::new(std::fs::File::create(path).expect("create diff"));
    let mut enc = png::Encoder::new(file, w as u32, h as u32);
    enc.set_color(png::ColorType::Rgb);
    enc.set_depth(png::BitDepth::Eight);
    enc.write_header().and_then(|mut wr| wr.write_image_data(&rgb)).expect("write diff");
}

/// Pixels per page that may differ (`INK_GOLDEN_TOLERANCE`, default 0).
fn tolerance() -> usize {
    std::env::var("INK_GOLDEN_TOLERANCE").ok().and_then(|v| v.parse().ok()).unwrap_or(0)
}

fn render(book: &Path, page: usize) -> Canvas {
    let mut doc = ink_formats::open(book).unwrap_or_else(|e| panic!("{}: {e}", book.display()));
    doc.set_layout(&LayoutSettings::for_screen(1272, 1696)).unwrap();
    let mut c = Canvas::new(1272, 1696);
    doc.render_page(page, &mut c).unwrap();
    c
}

#[test]
fn comparator_counts_a_single_pixel() {
    let a = Canvas::new(10, 10);
    let mut b = a.clone();
    assert_eq!(count_diff(&a, &b), Some(0));
    b.set(3, 4, 254);
    assert_eq!(count_diff(&a, &b), Some(1));
    assert_eq!(count_diff(&a, &Canvas::new(10, 11)), None);
}

type Case = (&'static str, &'static str, &'static [usize], Variant);

/// `f` on every case, results in CASES order. The cases are independent and juliet takes
/// most of the time, so they run on up to `available_parallelism` threads at once; one at
/// a time on ARM (the guest run in tests/e2e/html-tests-arm.sh has little memory).
fn on_threads<T: Send>(f: impl Fn(&Case) -> T + Sync) -> Vec<T> {
    let n = if cfg!(target_arch = "arm") { 1 } else { std::thread::available_parallelism().map_or(1, |n| n.get()) };
    let mut out = Vec::with_capacity(CASES.len());
    for chunk in CASES.chunks(n) {
        std::thread::scope(|sc| {
            let threads: Vec<_> = chunk.iter().map(|case| sc.spawn(|| f(case))).collect();
            out.extend(threads.into_iter().map(|t| t.join().unwrap()));
        });
    }
    out
}

#[test]
fn golden_pages() {
    let update = std::env::var("INK_GOLDEN_UPDATE").as_deref() == Ok("1");
    let gdir = golden_dir();
    let out = out_dir();
    let failures: Vec<String> = on_threads(|case| golden_case(case, update, &gdir, &out)).into_iter().flatten().collect();
    assert!(failures.is_empty(), "golden mismatches (actual/diff images in {}):\n{}", out.display(), failures.join("\n"));
}

/// Renders the pages of one golden case and compares them; returns the mismatches.
fn golden_case(&(name, book, pages, variant): &Case, update: bool, gdir: &Path, out: &Path) -> Vec<String> {
    let mut failures = Vec::new();
    {
        let book = root().join(book);
        // Open once per case: layout is the slow part.
        let mut doc = ink_formats::open(&book).unwrap_or_else(|e| panic!("{}: {e}", book.display()));
        doc.set_layout(&settings(variant)).unwrap();
        for &page in pages {
            let file = format!("{name}-p{:04}.png", page + 1);
            let golden = gdir.join(&file);
            let mut actual = Canvas::new(1272, 1696);
            doc.render_page(page, &mut actual).unwrap();
            let expected = Canvas::load_png(&golden).ok();
            let diff = expected.as_ref().and_then(|e| count_diff(e, &actual));
            if diff.is_some_and(|n| n <= tolerance()) {
                continue;
            }
            std::fs::create_dir_all(out).unwrap();
            actual.save_png(&out.join(file.replace(".png", ".actual.png"))).unwrap();
            if let Some(e) = &expected {
                write_diff(e, &actual, &out.join(file.replace(".png", ".diff.png")));
            }
            if update {
                std::fs::create_dir_all(gdir).unwrap();
                actual.save_png(&golden).unwrap();
                println!("updated {} ({})", golden.display(), match diff { Some(n) => format!("{n} pixels changed"), None => "new or resized".into() });
            } else {
                failures.push(match diff {
                    Some(n) => format!("{file}: {n} pixels differ"),
                    None if expected.is_none() => format!("{file}: golden missing (run scripts/golden-update.sh)"),
                    None => format!("{file}: size differs"),
                });
            }
        }
    }
    failures
}

#[test]
fn rendering_is_deterministic() {
    let book = root().join("testdata/synthetic.epub");
    assert_eq!(count_diff(&render(&book, 1), &render(&book, 1)), Some(0));
}

/// Page maps of the golden cases: every page start position of each case, hashed, in
/// `tests/golden/pagemaps.txt` under the engine version that made them. Cached page maps
/// are keyed by `paginate::ENGINE_VERSION`, so page breaks may only change together with
/// a bump of it: a changed hash under the same version fails, also in update mode.
/// (Named `golden_pages_...` so `scripts/golden-update.sh` runs it.)
#[test]
fn golden_pages_page_maps_match_engine_version() {
    use md5::{Digest, Md5};
    let update = std::env::var("INK_GOLDEN_UPDATE").as_deref() == Ok("1");
    let file = golden_dir().join("pagemaps.txt");
    let v = ink_html::paginate::ENGINE_VERSION;
    let mut lines = vec![format!("engine {v}")];
    let page_map_line = |&(name, book, _, variant): &Case| {
        let book = root().join(book);
        let mut doc = ink_formats::open(&book).unwrap_or_else(|e| panic!("{}: {e}", book.display()));
        doc.set_layout(&settings(variant)).unwrap();
        assert!(doc.wait_paginated(std::time::Duration::from_secs(600)), "{name}: pagination did not finish");
        let n = doc.page_count().pages;
        let mut h = Md5::new();
        for p in 0..n {
            h.update(doc.position_of_page(p).unwrap().to_string().as_bytes());
            h.update(b"\n");
        }
        let hex: String = h.finalize().iter().map(|b| format!("{b:02x}")).collect();
        format!("{name} {n} {hex}")
    };
    lines.extend(on_threads(page_map_line));
    let actual = lines.join("\n") + "\n";
    let expected = std::fs::read_to_string(&file).unwrap_or_default();
    if actual == expected {
        return;
    }
    let recorded: Option<u32> = expected.lines().next().and_then(|l| l.strip_prefix("engine ")).and_then(|x| x.trim().parse().ok());
    let changed: Vec<String> = actual.lines().filter(|l| !expected.lines().any(|e| e == *l)).map(str::to_string).collect();
    assert_ne!(
        recorded,
        Some(v),
        "page breaks changed under ENGINE_VERSION {v} (cached page maps would be wrong): bump ink_html::paginate::ENGINE_VERSION, then run scripts/golden-update.sh. Changed:\n{}",
        changed.join("\n")
    );
    if update {
        std::fs::write(&file, &actual).unwrap();
        println!("updated {} for engine {v}", file.display());
    } else {
        panic!("{} is for engine {recorded:?}, the code is {v}: run scripts/golden-update.sh", file.display());
    }
}
